MjpegDecodeAcceleratorAsyncWaiter::MjpegDecodeAcceleratorAsyncWaiter(
    MjpegDecodeAccelerator* proxy) : proxy_(proxy) {}

MjpegDecodeAcceleratorAsyncWaiter::~MjpegDecodeAcceleratorAsyncWaiter() = default;

void MjpegDecodeAcceleratorAsyncWaiter::Initialize(
    bool* out_success) {
  base::RunLoop loop;
  proxy_->Initialize(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}
void MjpegDecodeAcceleratorAsyncWaiter::DecodeWithDmaBuf(
    int32_t task_id, ::mojo::ScopedHandle src_dmabuf_fd, uint32_t src_size, uint32_t src_offset, ::cros::mojom::DmaBufVideoFramePtr dst_frame, DecodeError* out_error) {
  base::RunLoop loop;
  proxy_->DecodeWithDmaBuf(std::move(task_id),std::move(src_dmabuf_fd),std::move(src_size),std::move(src_offset),std::move(dst_frame),
      base::BindOnce(
          [](base::RunLoop* loop,
             DecodeError* out_error
,
             DecodeError error) {*out_error = std::move(error);
            loop->Quit();
          },
          &loop,
          out_error));
  loop.Run();
}





